package com.bjjj.todo;
import android.content.Context;import org.json.*;import java.time.*;import java.util.*;
final class Recurrence {
 static JSONObject calendar;
 static synchronized void init(Context c){if(calendar!=null)return;try(java.io.InputStream in=c.getAssets().open("workdays.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);calendar=new JSONObject(out.toString("UTF-8"));}catch(Exception e){throw new IllegalStateException("工作日数据无法读取",e);}}
 static String rule(JSONObject t){return t.optString("repeat","none");}
 static boolean repeats(JSONObject t){return !rule(t).equals("none")&&!rule(t).isEmpty();}
 static LocalDate start(JSONObject t){return Instant.parse(t.optString("due")).atZone(ZoneId.systemDefault()).toLocalDate();}
 static Boolean workday(LocalDate d){int y=d.getYear();if(y!=2026&&y!=2027)return null;JSONObject days=calendar.optJSONObject("days");return days.has(d.toString())?days.optBoolean(d.toString()):d.getDayOfWeek().getValue()<6;}
 static boolean matches(JSONObject t,LocalDate d){if(!repeats(t)||t.optBoolean("done")||d.isBefore(start(t)))return false;return switch(rule(t)){case "daily"->true;case "weekly"->d.getDayOfWeek()==start(t).getDayOfWeek();case "weekdays"->d.getDayOfWeek().getValue()<6;case "workdays"->Boolean.TRUE.equals(workday(d));default->false;};}
 static boolean completed(JSONObject t,String day){JSONArray a=t.optJSONArray("completedDates");if(a!=null)for(int i=0;i<a.length();i++)if(day.equals(a.optString(i)))return true;return false;}
 static JSONObject occurrence(JSONObject t,LocalDate d)throws Exception{if(!matches(t,d))return null;JSONObject out=new JSONObject(t.toString());LocalTime time=Instant.parse(t.getString("due")).atZone(ZoneId.systemDefault()).toLocalTime();out.put("seriesId",t.getString("id")).put("id",t.getString("id")+"@"+d).put("occurrenceDate",d.toString()).put("due",d.atTime(time).atZone(ZoneId.systemDefault()).toInstant().toString()).put("done",completed(t,d.toString()));return out;}
 static List<JSONObject> current(JSONObject root,LocalDate day){List<JSONObject> list=new ArrayList<>();try{JSONArray tasks=root.getJSONArray("tasks");for(int i=0;i<tasks.length();i++){JSONObject t=tasks.getJSONObject(i),item=repeats(t)?occurrence(t,day):t;if(item!=null&&!item.optBoolean("done"))list.add(item);}}catch(Exception e){throw new IllegalStateException(e);}list.sort(Comparator.comparingLong(Store::due));return list;}
 static List<JSONObject> reminders(JSONObject root)throws Exception{List<JSONObject> list=new ArrayList<>();JSONArray tasks=root.getJSONArray("tasks");LocalDate today=LocalDate.now();long now=System.currentTimeMillis();for(int i=0;i<tasks.length();i++){JSONObject t=tasks.getJSONObject(i);if(!repeats(t)){if(!t.optBoolean("done"))list.add(t);continue;}Set<LocalDate> days=new TreeSet<>();days.add(today);JSONArray offsets=t.optJSONArray("offsets");if(offsets!=null)for(int j=0;j<offsets.length();j++){double offset=offsets.optDouble(j);LocalDate base=Instant.ofEpochMilli(now+Math.round(offset*60000)).atZone(ZoneId.systemDefault()).toLocalDate();for(int n=-1;n<=16;n++){LocalDate day=base.plusDays(n);if(day.isBefore(today))continue;JSONObject item=occurrence(t,day);if(item!=null&&!item.optBoolean("done")){days.add(day);if(Store.due(item)-Math.round(offset*60000)>now)break;}}}for(LocalDate day:days){JSONObject item=occurrence(t,day);if(item!=null&&!item.optBoolean("done"))list.add(item);}}return list;}
 static String id(String value){return value.split("@",2)[0];}
 static JSONObject original(JSONObject root,JSONObject item)throws Exception{String id=item.optString("seriesId",item.getString("id"));JSONArray a=root.getJSONArray("tasks");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id))return a.getJSONObject(i);throw new Exception("事项不存在");}
 static void done(JSONObject t,String id,boolean value)throws Exception{if(!repeats(t)){t.put("done",value).put("completed",value?Instant.now().toString():"");return;}String[] parts=id.split("@",2);String day=parts.length>1?parts[1]:LocalDate.now().toString();if(!matches(t,LocalDate.parse(day)))throw new Exception("日期不在事项周期内");Set<String> set=new TreeSet<>();JSONArray old=t.optJSONArray("completedDates");if(old!=null)for(int i=0;i<old.length();i++)set.add(old.getString(i));if(value)set.add(day);else set.remove(day);if(set.size()>10000)throw new Exception("周期完成记录已达上限");t.put("completedDates",new JSONArray(set));}
 static String label(JSONObject t){return switch(rule(t)){case "daily"->"每天";case "weekly"->"每周";case "weekdays"->"周一至周五";case "workdays"->"法定工作日";default->"";};}
}
